import React, { useState, useEffect, useRef } from 'react';

const Explore = ({ onSelectStock }) => {
    const [indices, setIndices] = useState({});
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [showSearchResults, setShowSearchResults] = useState(false);
    const [recentlyViewed, setRecentlyViewed] = useState([]);
    const [popularStocks, setPopularStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchLoading, setSearchLoading] = useState(false);
    const [marketLoading, setMarketLoading] = useState(true);
    const searchRef = useRef(null);

    useEffect(() => {
        fetchIndices();
        fetchPopularStocks();
        const saved = localStorage.getItem('recentlyViewed');
        if (saved) {
            setRecentlyViewed(JSON.parse(saved));
        }

        // Auto-refresh market data every 30 seconds
        const interval = setInterval(() => {
            fetchIndices();
            fetchPopularStocks();
        }, 30000);

        const handleClickOutside = (event) => {
            if (searchRef.current && !searchRef.current.contains(event.target)) {
                setShowSearchResults(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        
        return () => {
            clearInterval(interval);
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    const fetchIndices = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/index-data');
            const data = await response.json();
            setIndices(data);
            setMarketLoading(false);
        } catch (error) {
            console.error('Error fetching indices:', error);
            setMarketLoading(false);
        }
    };

    const fetchPopularStocks = async () => {
        const popular = ['RELIANCE', 'TCS', 'HDFCBANK', 'INFY', 'ICICIBANK', 'SBIN', 'BHARTIARTL', 'ITC', 'WIPRO', 'HCLTECH'];
        try {
            const response = await fetch('http://localhost:5000/api/prices', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ symbols: popular })
            });
            const data = await response.json();
            const stocksWithData = popular.map(symbol => ({
                symbol,
                price: data[symbol] || null,
                change: null
            }));
            setPopularStocks(stocksWithData);
        } catch (error) {
            console.error('Error fetching popular stocks:', error);
        }
    };

    const handleSearch = async (query) => {
        setSearchQuery(query);
        if (query.length < 1) {
            setSearchResults([]);
            setShowSearchResults(false);
            return;
        }

        setSearchLoading(true);
        try {
            const response = await fetch(`http://localhost:5000/api/search/${query}`);
            const data = await response.json();
            setSearchResults(data || []);
            setShowSearchResults(true);
        } catch (error) {
            console.error('Error searching:', error);
            setSearchResults([]);
        }
        setSearchLoading(false);
    };

    const addToRecentlyViewed = (symbol) => {
        const updated = [symbol, ...recentlyViewed.filter(s => s !== symbol)].slice(0, 10);
        setRecentlyViewed(updated);
        localStorage.setItem('recentlyViewed', JSON.stringify(updated));
    };

    const handleStockClick = (symbol) => {
        addToRecentlyViewed(symbol);
        setShowSearchResults(false);
        setSearchQuery('');
        onSelectStock(symbol);
    };

    return (
        <div style={{ padding: '0', maxWidth: '100%' }}>
            {/* Market Indices - Live at Top */}
            <div style={{
                display: 'flex',
                gap: '30px',
                padding: '15px 20px',
                background: '#141b2b',
                borderRadius: '10px',
                border: '1px solid #2a3a5c',
                marginBottom: '20px',
                flexWrap: 'wrap',
                overflowX: 'auto'
            }}>
                {marketLoading ? (
                    <div style={{ color: '#8a9bb5' }}>Loading market data...</div>
                ) : (
                    Object.entries(indices).map(([name, data]) => (
                        <div key={name} style={{ display: 'flex', alignItems: 'center', gap: '10px', minWidth: '150px' }}>
                            <span style={{ fontWeight: 'bold', color: '#8a9bb5', fontSize: '14px' }}>
                                {name}
                            </span>
                            <span style={{ fontSize: '18px', fontWeight: 'bold', color: '#e0e6ed' }}>
                                {data.value ? data.value.toFixed(2) : 'N/A'}
                            </span>
                            <span style={{
                                color: data.change && data.change >= 0 ? '#4CAF50' : '#dc3545',
                                fontSize: '14px',
                                fontWeight: 'bold'
                            }}>
                                {data.change && data.change >= 0 ? '+' : ''}{data.change ? data.change.toFixed(2) : '0'}
                                ({data.change_percent ? data.change_percent.toFixed(2) : '0'}%)
                            </span>
                        </div>
                    ))
                )}
            </div>

            {/* Search Bar */}
            <div ref={searchRef} style={{ marginBottom: '20px', position: 'relative' }}>
                <div style={{ position: 'relative' }}>
                    <input
                        type="text"
                        placeholder="🔍 Search stocks (e.g., RELIANCE, TCS)"
                        value={searchQuery}
                        onChange={(e) => handleSearch(e.target.value)}
                        onFocus={() => searchQuery.length >= 1 && setShowSearchResults(true)}
                        style={{
                            width: '100%',
                            padding: '14px 20px',
                            paddingRight: '40px',
                            background: '#1a2332',
                            border: '2px solid #2a3a5c',
                            borderRadius: '10px',
                            color: 'white',
                            fontSize: '16px',
                            outline: 'none',
                            transition: 'border-color 0.2s'
                        }}
                    />
                    {searchLoading && (
                        <div style={{
                            position: 'absolute',
                            right: '15px',
                            top: '50%',
                            transform: 'translateY(-50%)',
                            color: '#8a9bb5'
                        }}>
                            ⏳
                        </div>
                    )}
                </div>

                {/* Search Results */}
                {showSearchResults && searchResults.length > 0 && (
                    <div style={{
                        position: 'absolute',
                        top: '100%',
                        left: 0,
                        right: 0,
                        marginTop: '4px',
                        background: '#141b2b',
                        border: '1px solid #2a3a5c',
                        borderRadius: '10px',
                        maxHeight: '400px',
                        overflowY: 'auto',
                        zIndex: 1000,
                        boxShadow: '0 10px 40px rgba(0,0,0,0.5)'
                    }}>
                        {searchResults.map((stock) => (
                            <div
                                key={stock.symbol}
                                onClick={() => handleStockClick(stock.symbol)}
                                style={{
                                    padding: '12px 16px',
                                    cursor: 'pointer',
                                    borderBottom: '1px solid #2a3a5c',
                                    transition: 'background 0.2s',
                                    display: 'flex',
                                    justifyContent: 'space-between',
                                    alignItems: 'center'
                                }}
                                onMouseEnter={(e) => e.target.style.background = '#1a2332'}
                                onMouseLeave={(e) => e.target.style.background = 'transparent'}
                            >
                                <div>
                                    <div style={{ fontWeight: 'bold', fontSize: '16px', color: '#e0e6ed' }}>
                                        {stock.symbol}
                                    </div>
                                    <div style={{ fontSize: '13px', color: '#8a9bb5' }}>
                                        {stock.name}
                                    </div>
                                </div>
                                <div style={{ textAlign: 'right' }}>
                                    {stock.price ? (
                                        <>
                                            <div style={{ fontWeight: 'bold', fontSize: '16px', color: '#e0e6ed' }}>
                                                ₹{stock.price.toFixed(2)}
                                            </div>
                                            {stock.change_percent !== null && (
                                                <div style={{
                                                    fontSize: '13px',
                                                    color: stock.change_percent >= 0 ? '#4CAF50' : '#dc3545',
                                                    fontWeight: 'bold'
                                                }}>
                                                    {stock.change_percent >= 0 ? '+' : ''}{stock.change_percent.toFixed(2)}%
                                                </div>
                                            )}
                                        </>
                                    ) : (
                                        <div style={{ color: '#8a9bb5', fontSize: '13px' }}>Loading...</div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {showSearchResults && searchQuery.length >= 1 && searchResults.length === 0 && !searchLoading && (
                    <div style={{
                        position: 'absolute',
                        top: '100%',
                        left: 0,
                        right: 0,
                        marginTop: '4px',
                        padding: '15px',
                        background: '#141b2b',
                        border: '1px solid #2a3a5c',
                        borderRadius: '10px',
                        color: '#8a9bb5',
                        textAlign: 'center'
                    }}>
                        No stocks found. Try searching with a different symbol.
                    </div>
                )}
            </div>

            {/* Recently Viewed */}
            {recentlyViewed.length > 0 && (
                <div style={{ marginBottom: '20px' }}>
                    <div style={{ 
                        display: 'flex', 
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        marginBottom: '10px'
                    }}>
                        <h3 style={{ color: '#e0e6ed', fontSize: '16px', margin: 0 }}>Recently viewed</h3>
                    </div>
                    <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                        {recentlyViewed.map((symbol) => (
                            <div
                                key={symbol}
                                onClick={() => handleStockClick(symbol)}
                                style={{
                                    padding: '8px 16px',
                                    background: '#1a2332',
                                    borderRadius: '20px',
                                    border: '1px solid #2a3a5c',
                                    cursor: 'pointer',
                                    color: '#e0e6ed',
                                    fontSize: '14px',
                                    transition: 'all 0.2s'
                                }}
                                onMouseEnter={(e) => e.target.style.background = '#2a3a5c'}
                                onMouseLeave={(e) => e.target.style.background = '#1a2332'}
                            >
                                {symbol}
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Most Traded Stocks */}
            <div>
                <h3 style={{ color: '#e0e6ed', fontSize: '16px', marginBottom: '10px' }}>
                    Most traded on Groww
                </h3>
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
                    gap: '10px'
                }}>
                    {popularStocks.map((stock) => (
                        <div
                            key={stock.symbol}
                            onClick={() => handleStockClick(stock.symbol)}
                            style={{
                                padding: '12px 16px',
                                background: '#141b2b',
                                borderRadius: '8px',
                                border: '1px solid #2a3a5c',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#1a2332'}
                            onMouseLeave={(e) => e.target.style.background = '#141b2b'}
                        >
                            <div>
                                <div style={{ color: '#e0e6ed', fontWeight: 'bold', fontSize: '14px' }}>
                                    {stock.symbol}
                                </div>
                                <div style={{ color: '#8a9bb5', fontSize: '12px' }}>
                                    {stock.price ? `₹${stock.price.toFixed(2)}` : 'N/A'}
                                </div>
                            </div>
                            <span style={{
                                color: '#8a9bb5',
                                fontSize: '12px'
                            }}>
                                ▶
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Explore;
